export const renderChartTypeIcon = (type: string, size = 19, className = "") => {
  switch (type) {
    case "Line":
      return <LineChartTypeIcon size={size} className={className} />;
    case "Mountain":
      return <MountainChartTypeIcon size={size} className={className} />;
    case "Bar":
      return <BarChartTypeIcon size={size} className={className} />;
    case "Heikin Ashi":
      return <HeikinAshiChartTypeIcon size={size} className={className} />;
    case "Candle":
    default:
      return <CandleChartTypeIcon size={size} className={className} />;
  }
};


