const getTimeSeconds = (tf: string) => {
  if (!tf || typeof tf !== 'string') return 60;
  const clean = tf.trim();
  const match = clean.match(/^(\d+)\s*([a-zA-Z]*)$/);
  if (!match) return 60;
  const val = parseInt(match[1]) || 1;
  const unit = match[2]?.toLowerCase() || '';
  if (unit.startsWith("s")) return val;
  if (unit.startsWith("m")) return val * 60;
  if (unit.startsWith("h")) return val * 3600;
  if (unit.startsWith("d")) return val * 86400;
  return val || 60;
};

const formatTimeframeShort = (tf: string) => {
  if (!tf || typeof tf !== 'string') return "";
  const clean = tf.trim();
  const match = clean.match(/^(\d+)\s*([a-zA-Z]*)$/);
  if (!match) return tf;
  const val = match[1];
  const unit = match[2] ? match[2][0].toLowerCase() : '';
  return `${val}${unit}`;
};

const isRealMarketClosed = (pair: string, time: Date = new Date()): boolean => {
  if (!pair) return false;
  const isOTC = pair.includes('(OTC)') || pair.includes('Crypto IDX');
  if (isOTC) {
    return false;
  }

  const isCrypto = pair.includes('/USD') && !(
    pair.startsWith('EUR/') || pair.startsWith('GBP/') || pair.startsWith('AUD/') || 
    pair.startsWith('NZD/') || pair.startsWith('USD/') || pair.startsWith('CAD/') || 
    pair.startsWith('CHF/') || pair.startsWith('JPY/') || pair.startsWith('DKK/') || 
    pair.startsWith('SEK/') || pair.startsWith('NOK/') || pair.startsWith('PLN/') || 
    pair.startsWith('HUF/') || pair.startsWith('CZK/') || pair.startsWith('ILS/') || 
    pair.startsWith('THB/') || pair.startsWith('TRY/') || pair.startsWith('SGD/')
  );

  if (isCrypto) {
    return false;
  }

  const day = time.getUTCDay(); // 0 = Sunday, 6 = Saturday
  const hours = time.getUTCHours();

  // Weekend closed hours: Friday 21:00 UTC to Sunday 22:00 UTC
  if (day === 6) {
    return true; // Saturday is always closed
  }
  if (day === 5 && hours >= 21) {
    return true; // Friday after 21:00 UTC is closed
  }
  if (day === 0 && hours < 22) {
    return true; // Sunday before 22:00 UTC is closed
  }

  // Specific Stock hours (e.g., Yum Brands): 13:30 to 20:00 UTC Mon-Fri
  if (pair === 'Yum Brands') {
    if (hours < 13 || hours >= 20) {
      return true;
    }
  }

  return false;
};

const calculateHeikinAshi = (data: any[]) => {
  if (!data || data.length === 0) return [];
  let haData = [];
  let prevOpen = data[0]?.open || 0;
  let prevClose = data[0]?.close || 0;

  for (let i = 0; i < data.length; i++) {
    const haClose =
      (data[i].open + data[i].high + data[i].low + data[i].close) / 4;
    const haOpen = (prevOpen + prevClose) / 2;
    const haHigh = Math.max(data[i].high, haOpen, haClose);
    const haLow = Math.min(data[i].low, haOpen, haClose);

    haData.push({
      time: data[i].time,
      open: haOpen,
      high: haHigh,
      low: haLow,
      close: haClose,
    });

    prevOpen = haOpen;
    prevClose = haClose;
  }
  return haData;
};

const resampleData = (data: any[], tfString: string) => {
  const timeframeSeconds = getTimeSeconds(tfString);
  if (!data || !Array.isArray(data) || data.length === 0) return [];
  
  const tfSecs = timeframeSeconds;
  if (!tfSecs || tfSecs <= 0) return data;

  // 1. Sanitize input items and sort strictly by timestamp ascending
  const cleanData = data
    .map((d: any) => {
      const time = Number(d?.time ?? d?.openTime ?? 0);
      const open = Number(d?.open ?? d?.close ?? 0);
      const close = Number(d?.close ?? open);
      const high = Number(d?.high ?? Math.max(open, close));
      const low = Number(d?.low ?? Math.min(open, close));
      const volume = Number(d?.volume ?? 0);
      return { time, open, high, low, close, volume };
    })
    .filter((d: any) => d.time > 0 && isFinite(d.open) && isFinite(d.close) && d.open > 0)
    .sort((a: any, b: any) => a.time - b.time);

  if (cleanData.length === 0) return [];

  // 2. Aggregate into exact timeframe buckets
  const bucketMap = new Map<number, any>();
  for (let i = 0; i < cleanData.length; i++) {
    const d = cleanData[i];
    const bucketTime = Math.floor(d.time / tfSecs) * tfSecs;

    if (!bucketMap.has(bucketTime)) {
      bucketMap.set(bucketTime, {
        time: bucketTime as Time,
        open: d.open,
        high: Math.max(d.open, d.close, d.high),
        low: Math.min(d.open, d.close, d.low),
        close: d.close,
        volume: d.volume
      });
    } else {
      const b = bucketMap.get(bucketTime)!;
      b.high = Math.max(b.high, d.high, d.open, d.close);
      b.low = Math.min(b.low, d.low, d.open, d.close);
      b.close = d.close;
      b.volume += d.volume;
    }
  }

  const sortedBuckets = Array.from(bucketMap.values()).sort((a: any, b: any) => (a.time as number) - (b.time as number));
  if (sortedBuckets.length === 0) return [];

  // 3. Build gapless, perfectly continuous candles with open = prevClose
  const continuous: any[] = [];
  let prevClose = sortedBuckets[0].open;

  for (let i = 0; i < sortedBuckets.length; i++) {
    const curr = sortedBuckets[i];
    const currTime = curr.time as number;

    // Fill missing time buckets if any (up to 30 buckets; if gap is larger, reset prevClose to prevent stretching old prices)
    if (continuous.length > 0) {
      const lastTime = continuous[continuous.length - 1].time as number;
      let gapTime = lastTime + tfSecs;
      const missingCount = Math.floor((currTime - gapTime) / tfSecs);
      if (missingCount > 30) {
        prevClose = curr.open;
      } else {
        while (gapTime < currTime && continuous.length < 3000) {
          continuous.push({
            time: gapTime as Time,
            open: prevClose,
            high: prevClose,
            low: prevClose,
            close: prevClose,
            volume: 0
          });
          gapTime += tfSecs;
        }
      }
    }

    // Guard against abnormal jumps between unrelated historical chunks (e.g. asset mismatch)
    if (prevClose > 0 && Math.abs(curr.open - prevClose) / prevClose > 0.08) {
      prevClose = curr.open;
    }

    // Enforce open = prevClose so there are ZERO gap-ups or gap-downs between candle bodies
    const open = prevClose;
    const close = curr.close;
    const high = Math.max(curr.high, open, close);
    const low = Math.min(curr.low, open, close);

    const candle = {
      time: currTime as Time,
      open,
      high,
      low,
      close,
      volume: curr.volume
    };

    continuous.push(candle);
    prevClose = close;
  }

  return continuous;
};



