function mergeAndDeduplicateActiveTrades(serverTrades: any[], priorTrades: any[]): any[] {
  const now = Date.now();
  const normalizeTimestamp = (val: any) => {
    if (!val) return 0;
    if (typeof val === 'number') {
      return val < 10000000000 ? val * 1000 : val;
    }
    if (typeof val?.toDate === 'function') {
      return val.toDate().getTime();
    }
    if (val instanceof Date) {
      return val.getTime();
    }
    const parsed = new Date(val).getTime();
    return isNaN(parsed) ? 0 : parsed;
  };

  const normalizeTrade = (t: any) => {
    const rawExp = t.expirationTime || (t.expiryTime ? t.expiryTime * 1000 : (t.expiry_time ? t.expiry_time * 1000 : 0));
    let expMs = normalizeTimestamp(rawExp);
    const rawCreated = t.createdAt || t.created_at || t.entryTime || t.entry_time || 0;
    const createdMs = normalizeTimestamp(rawCreated) || now;
    const durationSec = t.duration || t.tradeDuration || 60;

    if (!expMs || expMs <= createdMs) {
      expMs = createdMs + (durationSec * 1000);
    }

    const timeLeftSec = Math.max(0, Math.floor((expMs - now) / 1000));
    const entryPrice = Number(t.entryPrice || t.entry_price || t.rate || t.strikePrice || 0);
    const amount = Number(t.amount || t.tradeAmount || 0);
    const asset = String(t.asset || t.marketId || t.market_id || '').toUpperCase();
    const type = String(t.type || t.direction || 'up').toLowerCase();
    const accountType = String(t.accountType || t.account_type || (t.isDemo || t.is_demo ? 'demo' : 'real')).toLowerCase();
    const fbId = t.firebaseId || t.firebase_id ? String(t.firebaseId || t.firebase_id) : (t.id && isNaN(Number(t.id)) && String(t.id).length > 15 ? String(t.id) : undefined);

    return {
      ...t,
      id: String(t.id || fbId || Math.random().toString()),
      firebaseId: fbId,
      firebase_id: fbId,
      asset,
      type,
      direction: type,
      amount,
      entryPrice,
      accountType,
      isDemo: accountType === 'demo',
      expirationTime: expMs,
      entryTime: createdMs / 1000,
      createdAt: createdMs,
      timeLeft: timeLeftSec,
      status: t.status || 'open'
    };
  };

  const allRaw = [...(serverTrades || []), ...(priorTrades || [])];
  const normalizedList = allRaw
    .map(normalizeTrade)
    .filter(t => (t.timeLeft > 0 || (t.expirationTime && (now - t.expirationTime < 30000))) && (t.status === 'open' || t.status === 'Open' || !t.status));

  const result: any[] = [];
  const idToIndex = new Map<string, number>();

  for (const item of normalizedList) {
    const id1 = String(item.id || '');
    const fb1 = String(item.firebaseId || item.firebase_id || '');
    const idx = (id1 && idToIndex.has(id1)) ? idToIndex.get(id1)! : ((fb1 && idToIndex.has(fb1)) ? idToIndex.get(fb1)! : -1);

    if (idx >= 0 && idx < result.length) {
      const existing = result[idx];
      const isItemServerId = !isNaN(Number(item.id));
      const merged = {
        ...existing,
        ...item,
        id: isItemServerId ? item.id : existing.id,
        firebaseId: existing.firebaseId || item.firebaseId || item.id,
        firebase_id: existing.firebase_id || item.firebase_id || item.id,
        entryPrice: item.entryPrice || existing.entryPrice,
        createdAt: Math.min(existing.createdAt || now, item.createdAt || now),
        expirationTime: item.expirationTime || existing.expirationTime,
        timeLeft: Math.max(existing.timeLeft, item.timeLeft)
      };
      result[idx] = merged;
      if (id1) idToIndex.set(id1, idx);
      if (fb1) idToIndex.set(fb1, idx);
      if (merged.id) idToIndex.set(String(merged.id), idx);
      if (merged.firebaseId) idToIndex.set(String(merged.firebaseId), idx);
    } else {
      const newIdx = result.length;
      result.push(item);
      if (id1) idToIndex.set(id1, newIdx);
      if (fb1) idToIndex.set(fb1, newIdx);
    }
  }

  return result.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
}

export function deduplicateUserTrades(trades: any[]): any[] {
  if (!Array.isArray(trades)) return [];
  const map = new Map<string, any>();
  const idToKey = new Map<string, string>();

  for (const t of trades) {
    if (!t) continue;
    const rawId = String(t.id || '');
    const fbId = String(t.firebaseId || t.firebase_id || '');
    const primaryKey = (!isNaN(Number(rawId)) && Number(rawId) > 0) ? rawId : (fbId || rawId || Math.random().toString());

    const existingKey = (rawId && idToKey.get(rawId)) || (fbId && idToKey.get(fbId)) || null;

    if (existingKey && map.has(existingKey)) {
      const existing = map.get(existingKey)!;
      const bestId = (!isNaN(Number(rawId)) && Number(rawId) > 0) ? rawId : existing.id;
      const bestFbId = fbId || existing.firebaseId || existing.firebase_id;
      const isSettled = t.status && t.status !== 'open' && t.status !== 'Open';

      const merged = {
        ...existing,
        ...t,
        id: bestId,
        firebaseId: bestFbId,
        firebase_id: bestFbId,
        status: isSettled ? t.status : existing.status,
        exitPrice: t.exitPrice ?? t.exit_price ?? existing.exitPrice ?? existing.exit_price,
        payoutAmount: t.payoutAmount ?? t.payout_amount ?? existing.payoutAmount ?? existing.payout_amount
      };
      map.set(existingKey, merged);
      if (rawId) idToKey.set(rawId, existingKey);
      if (fbId) idToKey.set(fbId, existingKey);
      if (bestId) idToKey.set(String(bestId), existingKey);
      if (bestFbId) idToKey.set(String(bestFbId), existingKey);
    } else {
      map.set(primaryKey, t);
      if (rawId) idToKey.set(rawId, primaryKey);
      if (fbId) idToKey.set(fbId, primaryKey);
    }
  }

  const result = Array.from(map.values());
  return result.sort((a, b) => {
    const t1 = Number(b.createdAt || b.created_at || b.entryTime || 0);
    const t2 = Number(a.createdAt || a.created_at || a.entryTime || 0);
    return t1 - t2;
  });
}

