    const preventZoom = (e: TouchEvent) => {
      if (e.touches && e.touches.length > 1) {
        if (!isChartElement(e.target)) {
          e.preventDefault();
        }
      }
    };

    const preventGestureZoom = (e: Event) => {
      if (!isChartElement(e.target)) {
        e.preventDefault();
      }
    };

    const preventWheelZoom = (e: WheelEvent) => {
      if (e.ctrlKey) {
        if (!isChartElement(e.target)) {
          e.preventDefault();
        }
      }
    };

    // Use passive: false to allow calling preventDefault() to block browser viewport zoom on non-chart elements
