  const [personalData, setPersonalData] = useState(() => {
    try {
      const saved = currentUser?.uid ? localStorage.getItem(`bivax_personal_data_${currentUser.uid}`) : null;
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed && typeof parsed === 'object') return parsed;
      }
    } catch (e) {}
    return {
      firstName: currentUser?.firstName || currentUser?.displayName?.split(" ")[0] || "User",
      lastName: currentUser?.lastName || currentUser?.displayName?.split(" ")[1] || "",
      gender: currentUser?.gender || "Male",
      day: currentUser?.birthDay || "--",
      month: currentUser?.birthMonth || "--",
      year: currentUser?.birthYear || "--",
      country: currentUser?.country || ""
    };
  });
  const [savedPersonalData, setSavedPersonalData] = useState(() => ({ ...personalData }));
  const personalDataRef = useRef(personalData);
  useEffect(() => {
    personalDataRef.current = personalData;
  }, [personalData]);

  useEffect(() => {
    if (currentUser) {
      let parsedDay = currentUser.birthDay || currentUser.birth_day;
      let parsedMonth = currentUser.birthMonth || currentUser.birth_month;
      let parsedYear = currentUser.birthYear || currentUser.birth_year;
      if (currentUser.dob) {
        try {
          const d = typeof currentUser.dob === 'string' ? JSON.parse(currentUser.dob) : currentUser.dob;
          if (d) {
            if (!parsedDay || parsedDay === '--' || parsedDay === '---') parsedDay = d.day;
            if (!parsedMonth || parsedMonth === '--' || parsedMonth === '---') parsedMonth = d.month;
            if (!parsedYear || parsedYear === '--' || parsedYear === '---') parsedYear = d.year;
          }
        } catch (e) {}
      }

      setPersonalData((prev: any) => ({
        firstName: currentUser.firstName || currentUser.first_name || prev.firstName,
        lastName: currentUser.lastName || currentUser.last_name || prev.lastName,
        gender: (currentUser.gender && currentUser.gender !== '---') ? currentUser.gender : prev.gender,
        day: (parsedDay && parsedDay !== '---') ? String(parsedDay) : prev.day,
        month: (parsedMonth && parsedMonth !== '---') ? String(parsedMonth) : prev.month,
        year: (parsedYear && parsedYear !== '---') ? String(parsedYear) : prev.year,
        country: currentUser.country || prev.country
      }));
    }
  }, [currentUser]);
  const [showSaveToast, setShowSaveToast] = useState(false);
  const [timeZone, setTimeZone] = useState(Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC");
  const timeZoneRef = useRef(timeZone);
