  const alignChartRightByIdx = (idx: number, fallbackLen: number = 0, delay: number = 50) => {
    const chart = idx === 0 ? chartRef.current : chartRef2.current;
    if (!chart) return;
    
    const applyAlign = () => {
      const c = idx === 0 ? chartRef.current : chartRef2.current;
      if (!c) return;
      try {
        const ts = c.timeScale();
        // User requested candles to be "centered" and "zoomed beautifully"
        // Increasing rightOffset and barSpacing while decreasing targetVisibleBars achieves this.
        const rOffset = isMobile ? 12 : 20;
        const targetVisibleBars = isMobile ? 30 : 55;
        
        ts.applyOptions({
          rightOffset: rOffset,
          barSpacing: isMobile ? 16 : 22,
        });

        const dataLen = fallbackLen > 0 ? fallbackLen : (idx === 0 ? (baseDataRef.current?.length || 250) : 250);
        if (dataLen > 0) {
          const toIndex = dataLen - 1 + rOffset;
          const fromIndex = toIndex - targetVisibleBars;
          ts.setVisibleLogicalRange({
            from: fromIndex,
            to: toIndex,
          });
        } else {
          ts.scrollToRealTime();
        }
      } catch (e) {}
    };

    applyAlign();
    if (delay > 0) {
      setTimeout(applyAlign, delay);
      setTimeout(applyAlign, delay + 150);
    }
  };

  useEffect(() => {
    let rafId: number;

    const renderFutureTimeGridAndAxis = (
      cIdx: number,
      cChart: any,
      cContainer: HTMLElement | null,
      isMobileView: boolean,
      currentTimeZone: string
    ) => {
      if (!cChart || !cContainer) return;
      const gridGroupEl = document.getElementById(`custom-time-grid-group-${cIdx}`);
      const axisGroupEl = document.getElementById(`custom-time-axis-group-${cIdx}`);
      if (!gridGroupEl && !axisGroupEl) return;

      const ts = cChart.timeScale();
      const visibleRange = ts.getVisibleLogicalRange();
      if (!visibleRange) return;

      const lastCandle = rawLastCandleRef.current || lastCandleRef.current;
      if (!lastCandle || !lastCandle.time) return;

      const lastCandleTime = typeof lastCandle.time === 'number' ? lastCandle.time : Math.floor(Date.now() / 1000);
      const tfSecs = getTimeSeconds(timeframeRef.current);
      const baseData = baseDataRef.current;
      const lastCandleLogicalIndex = (baseData && baseData.length > 0) ? baseData.length - 1 : 0;

      const startTime = lastCandleTime + (visibleRange.from - lastCandleLogicalIndex) * tfSecs;
      const endTime = lastCandleTime + (visibleRange.to - lastCandleLogicalIndex) * tfSecs;
      const totalDuration = endTime - startTime;
      if (totalDuration <= 0 || !isFinite(totalDuration)) return;

      const containerWidth = cContainer.clientWidth || 600;
      const containerHeight = cContainer.clientHeight || 400;

      // The chart is full-width with floating price scale
      const availableWidth = containerWidth;
      const targetTicks = Math.max(3, Math.min(10, Math.floor(availableWidth / (isMobileView ? 95 : 125))));
      const approxStep = totalDuration / targetTicks;

      const TIME_STEPS = [
        5, 10, 15, 20, 30, 60, 120, 180, 240, 300, 480, 600, 900, 1200, 1800, 3600, 7200, 14400, 28800, 43200, 86400
      ];

      let chosenStep = TIME_STEPS[TIME_STEPS.length - 1];
      for (const step of TIME_STEPS) {
        if (step >= approxStep) {
          chosenStep = step;
          break;
        }
      }

      const firstTick = Math.ceil(startTime / chosenStep) * chosenStep;
      const lastTick = Math.floor(endTime / chosenStep) * chosenStep;

      let gridSvgHtml = '';
      let axisSvgHtml = '';
      const axisY = containerHeight - 26;
      const textY = containerHeight - 8;
      const showSeconds = chosenStep < 60 || tfSecs < 60;

      for (let t = firstTick; t <= lastTick + 0.1; t += chosenStep) {
        const diffSecs = t - lastCandleTime;
        const logicalIdx = lastCandleLogicalIndex + (diffSecs / tfSecs);
        const x = ts.logicalToCoordinate(logicalIdx);

        if (x !== null && x >= 0 && x <= availableWidth) {
          // Vertical Grid Line across entire chart (including future space)
          gridSvgHtml += `<line x1="${x.toFixed(1)}" y1="0" x2="${x.toFixed(1)}" y2="${axisY}" stroke="rgba(255, 255, 255, 0.045)" stroke-width="1" />`;

          // Tick mark notch at bottom axis border
          axisSvgHtml += `<line x1="${x.toFixed(1)}" y1="${axisY}" x2="${x.toFixed(1)}" y2="${axisY + 4}" stroke="rgba(255, 255, 255, 0.09)" stroke-width="1" />`;

          // Format time
          const date = new Date(t * 1000);
          const timeLabel = date.toLocaleTimeString('en-US', {
            timeZone: currentTimeZone || 'UTC',
            hour: '2-digit',
            minute: '2-digit',
            second: showSeconds ? '2-digit' : undefined,
            hour12: false
          });

          // Text label centered at x
          axisSvgHtml += `<text x="${x.toFixed(1)}" y="${textY}" text-anchor="middle" fill="#8f94a6" font-size="10.5px" font-weight="500" font-family="JetBrains Mono, -apple-system, sans-serif">${timeLabel}</text>`;
        }
      }

      if (gridGroupEl && gridGroupEl.innerHTML !== gridSvgHtml) {
        gridGroupEl.innerHTML = gridSvgHtml;
      }
      if (axisGroupEl && axisGroupEl.innerHTML !== axisSvgHtml) {
        axisGroupEl.innerHTML = axisSvgHtml;
      }
    };

    const renderFloatingPriceAndHorizontalGrid = (
      cIdx: number,
      cChart: any,
      cSeries: any,
      cContainer: HTMLElement | null,
      isMobileView: boolean
    ) => {
      if (!cChart || !cSeries || !cContainer) return;
      const priceAxisEl = document.getElementById(`custom-price-axis-group-${cIdx}`);
      const horzGridEl = document.getElementById(`custom-horizontal-grid-group-${cIdx}`);
      if (!priceAxisEl && !horzGridEl) return;

      const containerWidth = cContainer.clientWidth || 600;
      const containerHeight = cContainer.clientHeight || 400;
      const axisY = containerHeight - 26;

      // Get top and bottom visible prices from coordinates
      const topPrice = cSeries.coordinateToPrice(15);
      const bottomPrice = cSeries.coordinateToPrice(axisY - 15);
      if (topPrice === null || bottomPrice === null || !isFinite(topPrice) || !isFinite(bottomPrice)) return;

      const minPrice = Math.min(topPrice, bottomPrice);
      const maxPrice = Math.max(topPrice, bottomPrice);
      const priceDiff = maxPrice - minPrice;
      if (priceDiff <= 0 || !isFinite(priceDiff)) return;

      const targetLines = Math.max(3, Math.min(8, Math.floor(axisY / 65)));
      const rawStep = priceDiff / targetLines;

      const power = Math.floor(Math.log10(rawStep));
      const magnitude = Math.pow(10, power);
      const normalized = rawStep / magnitude;
      let stepMultiplier = 1;
      if (normalized > 6) stepMultiplier = 10;
      else if (normalized > 3.5) stepMultiplier = 5;
      else if (normalized > 1.8) stepMultiplier = 2.5;
      else if (normalized > 1.2) stepMultiplier = 2;
      else stepMultiplier = 1;

      const step = stepMultiplier * magnitude;
      if (step <= 0 || !isFinite(step)) return;

      const firstTick = Math.ceil(minPrice / step) * step;
      const lastTick = Math.floor(maxPrice / step) * step;

      let decimals = 2;
      if (step < 0.00001) decimals = 6;
      else if (step < 0.0001) decimals = 5;
      else if (step < 0.001) decimals = 4;
      else if (step < 0.01) decimals = 3;
      else if (step < 0.1) decimals = 2;
      else if (step < 1) decimals = 1;
      else decimals = 0;

      let horzGridSvgHtml = '';
      let priceSvgHtml = '';
      const labelRightX = containerWidth - (isMobileView ? 6 : 10);

      for (let p = firstTick; p <= lastTick + (step * 0.05); p += step) {
        const y = cSeries.priceToCoordinate(p);
        if (y !== null && y >= 10 && y <= axisY - 8) {
          horzGridSvgHtml += `<line x1="0" y1="${y.toFixed(1)}" x2="${containerWidth}" y2="${y.toFixed(1)}" stroke="rgba(255, 255, 255, 0.045)" stroke-width="1" />`;

          const formattedPrice = p.toFixed(decimals);
          // Floating price text on the right edge over candles
          priceSvgHtml += `<text x="${labelRightX.toFixed(1)}" y="${(y + 3.5).toFixed(1)}" text-anchor="end" fill="#8f94a6" font-size="11px" font-weight="500" font-family="JetBrains Mono, -apple-system, sans-serif">${formattedPrice}</text>`;
        }
      }

      if (horzGridEl && horzGridEl.innerHTML !== horzGridSvgHtml) {
        horzGridEl.innerHTML = horzGridSvgHtml;
      }
      if (priceAxisEl && priceAxisEl.innerHTML !== priceSvgHtml) {
        priceAxisEl.innerHTML = priceSvgHtml;
      }
    };

    const updateLine = () => {
      try {
        const chartConfigs = (isMultiChart && !isMobile ? [0, 1] : [0]);
        
        const isLineOrMountain = chartTypeRef.current === "Line" || chartTypeRef.current === "Mountain";
        let newInterp = targetPriceRef.current;
        if (rawLastCandleRef.current && targetPriceRef.current > 0) {
             if (currentInterpolatedPriceRef.current === 0) {
                 currentInterpolatedPriceRef.current = targetPriceRef.current;
                 (window as any).interpolatedTargetNoise = 0;
                 (window as any).interpolatedCurrentNoise = 0;
                 (window as any).noiseFrameCount = 0;
             } else {
                 if (typeof (window as any).interpolatedTargetNoise === 'undefined') {
                     (window as any).interpolatedTargetNoise = 0;
                     (window as any).interpolatedCurrentNoise = 0;
                     (window as any).noiseFrameCount = 0;
                 }
                 
                 (window as any).noiseFrameCount++;
                 if ((window as any).noiseFrameCount >= 40) {
                     (window as any).noiseFrameCount = 0;
                     const unit = targetPriceRef.current * 0.0000003;
                     (window as any).interpolatedTargetNoise = (Math.random() - 0.5) * unit;
                 }
                 
                 (window as any).interpolatedCurrentNoise += ((window as any).interpolatedTargetNoise - (window as any).interpolatedCurrentNoise) * 0.05;
                 
                 const finalTargetPrice = targetPriceRef.current + (window as any).interpolatedCurrentNoise;
                 const diff = finalTargetPrice - currentInterpolatedPriceRef.current;
                 
                 // Dynamic, ultra-gentle 0.04 LERP factor for a silky-smooth, slow-gliding price line like Binomo
                 // This acts as a perfect mathematical low-pass filter to absorb any high-frequency jumps
                 currentInterpolatedPriceRef.current += diff * 0.04;
             }
             newInterp = currentInterpolatedPriceRef.current;
         }

         const needsSeriesUpdate = true;

        chartConfigs.forEach(idx => {
          const currentChart = idx === 0 ? chartRef.current : chartRef2.current;
          const currentSeries = idx === 0 ? seriesRef.current : seriesRef2.current;
          const currentContainer = idx === 0 ? chartContainerRef.current : chartContainerRef2.current;
          
          if (currentChart && currentContainer) {
             try {
                 const candlePair = ((rawLastCandleRef.current as any)?.pair || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                 const activePair = (activeAssetRef.current || '').toLowerCase().replace(/[^a-z0-9]/g, '');
                 const isMatchingActive = Boolean(rawLastCandleRef.current) && 
                     (!candlePair || !activePair || candlePair === activePair) && 
                     (!((rawLastCandleRef.current as any).tf) || (rawLastCandleRef.current as any).tf === timeframeRef.current);

                 if (currentSeries && isMatchingActive && newInterp > 0 && needsSeriesUpdate) {
                     const newCandle = { ...rawLastCandleRef.current };
                     newCandle.close = newInterp;
                     newCandle.high = Math.max(newCandle.high, newInterp);
                     newCandle.low = Math.min(newCandle.low, newInterp);

                     // Sync high and low back to ref so wicks are retained smoothly
                     rawLastCandleRef.current.high = newCandle.high;
                     rawLastCandleRef.current.low = newCandle.low;
                   
                   try {
                       if (chartTypeRef.current === "Line" || chartTypeRef.current === "Mountain") {
                           if (typeof newCandle.time === 'number' && isFinite(newCandle.time) && isFinite(newInterp)) {
                               currentSeries.update({ time: newCandle.time, value: newInterp });
                           }
                       } else {
                           currentSeries.update(newCandle);
                       }
                   } catch(updErr) {}
                   if (idx === 0) {
                       lastCandleRef.current = newCandle;
                   }
               }

               const ts = currentChart.timeScale();
               const tsWidth = currentContainer.clientWidth || 600;
               const visibleRange = ts.getVisibleLogicalRange();
               
               const timeSecs = Math.floor((purchaseDeadlineTimeRef.current || purchaseDeadlineTime) / 1000);
               const expSecs = Math.floor((exactExpirationTimeRef.current || exactExpirationTime) / 1000);
               
               const getX = (targetTimeSecs: number) => {
                   let x = ts.timeToCoordinate(targetTimeSecs as Time);
                   if (x === null && rawLastCandleRef.current) {
                       const lastTime = rawLastCandleRef.current.time as number;
                       const lastX = ts.timeToCoordinate(lastTime as Time);
                       if (lastX !== null && visibleRange) {
                           const secondsDiff = targetTimeSecs - lastTime;
                           const timeframeSeconds = getTimeSeconds(timeframe);
                           const candlesDiff = secondsDiff / timeframeSeconds;
                           const barSpacing = tsWidth / (visibleRange.to - visibleRange.from);
                           x = (lastX + candlesDiff * barSpacing) as any;
                       }
                   }
                   return x;
               };
               
               const pX = getX(timeSecs);
               const eX = getX(expSecs);

               const purchaseEl = document.getElementById(`custom-purchase-line-container-${idx}`);
               const expirationEl = document.getElementById(`custom-expiration-line-container-${idx}`);

               if (purchaseEl) {
                  if (pX !== null && pX > -100 && pX < (currentContainer?.clientWidth || 2000) + 100) {
                     purchaseEl.style.transform = `translateX(${pX}px)`;
                     purchaseEl.style.display = 'flex';
                  } else {
                     purchaseEl.style.display = 'none';
                  }
               }

               if (expirationEl) {
                  if (eX !== null && eX > -100 && eX < (currentContainer?.clientWidth || 2000) + 100) {
                     expirationEl.style.transform = `translateX(${eX}px)`;
                     expirationEl.style.display = 'flex';
                  } else {
                     expirationEl.style.display = 'none';
                  }
               }
               
               if (currentSeries && (lastCandleRef.current || rawLastCandleRef.current)) {
                   const priceY = currentSeries.priceToCoordinate(currentInterpolatedPriceRef.current);
                   
                   if (idx === 0) {
                      if (timerOverlayRef.current && priceY !== null) {
                          timerOverlayRef.current.style.transform = `translateY(${priceY}px)`;
                      }
                      if (hoverTradeTypeRef.current && lastCandleRef.current) {
                          const y = currentSeries.priceToCoordinate(lastCandleRef.current.close);
                          setHoverLineY(y);
                      } else {
                          setHoverLineY(null);
                      }
                   }

                   // Update custom Binomo-style price line and pulsating dot
                   const leftLineEl = document.getElementById(`custom-price-line-left-${idx}`);
                   const badgeGroupEl = document.getElementById(`custom-price-badge-group-${idx}`);
                   const badgeTextEl = document.getElementById(`custom-price-badge-text-${idx}`);
                   const badgeBgEl = document.getElementById(`custom-price-badge-bg-${idx}`);
                   const rightLineEl = document.getElementById(`custom-price-line-right-${idx}`);
                   
                   
                   if (leftLineEl || rightLineEl || badgeGroupEl) {
                       if (priceY !== null && priceY >= 0) {
                           let candleX: number | null = null;
                           const lastCandle = rawLastCandleRef.current || lastCandleRef.current;
                           if (lastCandle && (lastCandle as any).time) {
                               candleX = ts.timeToCoordinate((lastCandle as any).time as Time);
                           }
                           
                           const containerWidth = currentContainer?.clientWidth || 600;
                           // Fallback: If we can't find the candle X, it's usually near the right side
                           const effectiveCandleX = candleX !== null ? candleX : (containerWidth - 60); 

                                                       // Floating price badge width and position on the right border (Compact & sleek size)
                            const badgeWidth = isMobile ? 78 : 86;
                            const badgeXOffset = containerWidth - badgeWidth;
                            
                            if (leftLineEl) {
                                  leftLineEl.setAttribute('x1', '0');
                                  leftLineEl.setAttribute('y1', priceY.toString());
                                  leftLineEl.setAttribute('x2', effectiveCandleX.toString());
                                  leftLineEl.setAttribute('y2', priceY.toString());
                                  leftLineEl.setAttribute('stroke', 'rgba(255, 255, 255, 0.20)');
                                  leftLineEl.setAttribute('stroke-width', '1.0');
                                  leftLineEl.removeAttribute('stroke-linecap');
                                  leftLineEl.setAttribute('stroke-dasharray', '2 2.5');
                                  leftLineEl.style.display = 'block';
                              }
                             
                             if (rightLineEl) {
                                  rightLineEl.setAttribute('x1', effectiveCandleX.toString());
                                  rightLineEl.setAttribute('y1', priceY.toString());
                                  rightLineEl.setAttribute('x2', badgeXOffset.toString());
                                  rightLineEl.setAttribute('y2', priceY.toString());
                                  rightLineEl.setAttribute('stroke', 'rgba(255, 255, 255, 0.35)');
                                  rightLineEl.setAttribute('stroke-width', '1.0');
                                  rightLineEl.removeAttribute('stroke-linecap');
                                  rightLineEl.removeAttribute('stroke-dasharray');
                                  rightLineEl.style.display = 'block';
                              }

                            if (badgeGroupEl && badgeTextEl) {
                                 // Position vertically centered at priceY (H = 18px -> half height = 9px)
                                 badgeGroupEl.setAttribute('transform', `translate(${badgeXOffset}, ${priceY - 9})`);
                                 
                                 const currentPriceVal = currentInterpolatedPriceRef.current || 0;
                                 
                                 const getAssetPrecision = (assetName: string, val: number) => {
                                     const lower = (assetName || '').toLowerCase();
                                     if (lower.includes('crypto idx')) return 2;
                                     if (lower.includes('btc') || lower.includes('eth') || lower.includes('gold')) return 2;
                                     if (lower.includes('jpy')) return 3;
                                     if (lower.includes('/') || lower.includes('otc') || lower.includes('usd') || lower.includes('eur') || lower.includes('gbp') || lower.includes('sgd')) {
                                         return val > 0 && val < 10 ? 4 : 3;
                                     }
                                     if (val > 0) {
                                         if (val < 10) return 4;
                                         if (val < 100) return 3;
                                         return 2;
                                     }
                                     return 3;
                                 };
                                 
                                 const precision = getAssetPrecision(activeAssetRef.current || '', currentPriceVal);
                                 badgeTextEl.textContent = currentPriceVal.toFixed(precision);

                                 // Sleek, smaller Binomo-style price chevron tag (Height = 18px, Chevron Notch = 7px)
                                 const W = badgeWidth;
                                 const H = 18;
                                 const pathD = `M 0 9 L 7 0 L ${W - 4} 0 Q ${W} 0 ${W} 4 L ${W} ${H - 4} Q ${W} ${H} ${W - 4} ${H} L 7 ${H} Z`;
                                 if (badgeBgEl) {
                                     badgeBgEl.setAttribute('d', pathD);
                                     badgeBgEl.setAttribute('fill', '#3f434c'); // Sleek slate grey tag
                                     badgeBgEl.setAttribute('stroke', 'rgba(255, 255, 255, 0.20)');
                                     badgeBgEl.setAttribute('stroke-width', '0.8');
                                 }

                                 // Center text horizontally and vertically inside the compact badge body
                                 badgeTextEl.setAttribute('x', ((W + 7) / 2).toString());
                                 badgeTextEl.setAttribute('y', '9.5'); // Perfect vertical centering for 18px height badge
                                 badgeTextEl.setAttribute('fill', '#ffffff');
                                 badgeTextEl.setAttribute('font-weight', 'bold');
                                 badgeTextEl.setAttribute('font-size', isMobile ? '10.5px' : '11px');

                                 badgeGroupEl.style.display = 'block';
                             }

                           // Dynamic Gimbal Laser Radar Head Tracking removed
                        } else {
                           if (leftLineEl) leftLineEl.style.display = 'none';
                           if (rightLineEl) rightLineEl.style.display = 'none';
                           if (badgeGroupEl) badgeGroupEl.style.display = 'none';
                           const gimbalDotGroupEl = document.getElementById(`custom-gimbal-dot-group-${idx}`);
                           if (gimbalDotGroupEl) gimbalDotGroupEl.style.display = 'none';
                       }
                   }

                   if (activeTradesRef.current && activeAssetRef.current) {
                       const currentPrice = lastCandleRef.current?.close ?? rawLastCandleRef.current?.close ?? lastCandleRef.current?.value;
                       let candleHalfWidth = 0;
                       if (visibleRange && (visibleRange.to - visibleRange.from) > 0) {
                           const barSpacing = tsWidth / (visibleRange.to - visibleRange.from);
                           candleHalfWidth = barSpacing * 0.40;
                       }

                       activeTradesRef.current.forEach(trade => {
                           const isMatchingAsset = trade.asset === activeAssetRef.current || 
                                                   (trade as any).marketId === activeAssetRef.current || 
                                                   (trade as any).market_id === activeAssetRef.current ||
                                                   (trade.asset && activeAssetRef.current && trade.asset.toLowerCase().replace(/[^a-z0-9]/g, '') === activeAssetRef.current.toLowerCase().replace(/[^a-z0-9]/g, ''));
                           if (isMatchingAsset) {
                               const elId = `trade-overlay-${idx}-${trade.id}`;
                               let el = tradeElementsRef.current.get(elId);
                               if (!el || !el.isConnected) {
                                   el = document.getElementById(elId) as HTMLElement;
                                   if (!el && (trade as any).firebaseId) {
                                       el = document.getElementById(`trade-overlay-${idx}-${(trade as any).firebaseId}`) as HTMLElement;
                                   }
                                   if (!el && (trade as any).firebase_id) {
                                       el = document.getElementById(`trade-overlay-${idx}-${(trade as any).firebase_id}`) as HTMLElement;
                                   }
                                   if (!el) {
                                       const parent = document.getElementById(`active-trades-overlays-${idx}`);
                                       if (parent) {
                                           el = (parent.querySelector(`[data-trade-id="${trade.id}"]`) as HTMLElement) ||
                                                (parent.querySelector(`[data-fb-id="${trade.id}"]`) as HTMLElement);
                                       }
                                   }
                                   if (el) tradeElementsRef.current.set(elId, el);
                               }
                               
                               if (el) {
                                   const y = currentSeries.priceToCoordinate(Number(trade.entryPrice));
                                   const entryTimeSecs = (trade.entryTime || (typeof trade.createdAt === 'number' ? Math.floor(trade.createdAt / 1000) : (trade.createdAt && typeof (trade.createdAt as any).toDate === 'function' ? Math.floor((trade.createdAt as any).toDate().getTime() / 1000) : ((trade.createdAt as any) instanceof Date ? Math.floor((trade.createdAt as any).getTime() / 1000) : Math.floor(Date.now() / 1000)))));
                                   let xBase = getX(entryTimeSecs as number);
                                   if (xBase === null) {
                                       const lastTime = (rawLastCandleRef.current?.time || (lastCandleRef.current as any)?.time) as number;
                                       if (lastTime) xBase = ts.timeToCoordinate(lastTime as Time);
                                   }
                                   const xExp = getX(Math.floor(trade.expirationTime / 1000));
                                   
                                   const adjXBase = xBase !== null ? xBase - candleHalfWidth : null;
                                   
                                   if (y !== null && adjXBase !== null) {
                                       el.style.transform = `translate(${adjXBase}px, ${y}px)`;
                                       if (el.style.display !== 'block') el.style.display = 'block';
                                       
                                       const isProfit = isTradeUpDirection(trade) ? currentPrice > trade.entryPrice : currentPrice < trade.entryPrice;
                                       const line = el.querySelector('.trade-line') as HTMLElement;
                                       const dot = el.querySelector('.trade-dot') as HTMLElement;
                                       
                                       if (line) {
                                           if (isProfit) {
                                               line.style.borderBottom = `2px dotted #FCD535`;
                                               line.style.opacity = '1';
                                           } else {
                                               line.style.borderBottom = '2px dotted rgba(252, 213, 53, 0.5)';
                                               line.style.opacity = '0.6';
                                           }
                                       }
                                       
                                       if (dot) {
                                           if (isProfit) {
                                               dot.style.transform = 'scale(1.2)';
                                               dot.style.backgroundColor = '#FCD535';
                                           } else {
                                               dot.style.transform = 'scale(1)';
                                               dot.style.backgroundColor = 'rgba(252, 213, 53, 0.7)';
                                           }
                                       }

                                       const arrow = el.querySelector('.trade-arrow') as HTMLElement;
                                       if (arrow) {
                                           const arrowTip = arrow.querySelector('div') as HTMLElement;
                                           if (arrowTip) {
                                               if (isProfit) {
                                                   arrowTip.style.borderTopColor = '#FCD535';
                                                   arrow.style.opacity = '1';
                                               } else {
                                                   arrowTip.style.borderTopColor = 'rgba(252, 213, 53, 0.5)';
                                                   arrow.style.opacity = '0.7';
                                               }
                                           }
                                       }

                                       if (xExp !== null && xExp > adjXBase!) {
                                           const newWidth = `${Math.max(1, xExp - adjXBase!)}px`;
                                           if (el.style.width !== newWidth) el.style.width = newWidth;
                                       } else if (xExp !== null) {
                                           if (el.style.width !== '0px') el.style.width = '0px';
                                       } else {
                                           const targetExpX = eX !== null ? eX : (adjXBase + 60);
                                           const newWidth = `${Math.max(1, Math.round(targetExpX - adjXBase))}px`;
                                           if (el.style.width !== newWidth) el.style.width = newWidth;
                                       }
                                   } else {
                                       if (el.style.display !== 'none') el.style.display = 'none';
                                   }
                               }
                           }
                       });
                   }
               }

               // Render floating price scale & horizontal grid lines (candles visible underneath)
               renderFloatingPriceAndHorizontalGrid(idx, currentChart, currentSeries, currentContainer, isMobile);

               // Render real-time & future time grid and axis labels extending to right border
               renderFutureTimeGridAndAxis(idx, currentChart, currentContainer, isMobile, timeZoneRef.current);
           } catch(e) {
               console.warn("Error in updateLine for chart idx " + idx, e);
           }
        }
      });
      
      lastRenderedPriceRef.current = newInterp;
      lastRenderedTimeRef.current = rawLastCandleRef.current?.time as number || 0;
      } catch (loopErr) {
        console.warn("Uncaught issue in updateLine frame:", loopErr);
      } finally {
        rafId = requestAnimationFrame(updateLine);
      }
    };
    rafId = requestAnimationFrame(updateLine);
    return () => cancelAnimationFrame(rafId);
  }, [timeframe]);

  // Price Alert & Trades States
  const [alerts, setAlerts] = useState<any[]>([]);
  const alertsRef = React.useRef<any[]>([]);

  useEffect(() => {
    let unsubAlerts: () => void = () => {};
    const unsubAuth = onAuthStateChanged(auth, (user) => {
        if (user) {
            const q = query(collection(db, 'users', user.uid, 'priceAlerts'), where('status', '==', 'active'));
            unsubAlerts = onSnapshot(q, (snapshot) => {
                const loadedAlerts: any[] = [];
                snapshot.forEach(doc => loadedAlerts.push({id: doc.id, ...doc.data()}));
                setAlerts(loadedAlerts);
                alertsRef.current = loadedAlerts;
            }, (error) => console.warn("Failed to watch price alerts:", error.message));
        } else {
            setAlerts([]);
            alertsRef.current = [];
            if (unsubAlerts) unsubAlerts();
        }
    });

    return () => {
        unsubAuth();
        if (unsubAlerts) unsubAlerts();
    };
  }, []);

  useEffect(() => {
    if (currentUser?.uid && appConfig?.loginPromoAd_enabled) {
        // Prevent showing on initial load if we don't have a fresh sign-in attempt
        // We use sessionStorage to ensure it pops up once per app session upon login
        const shownKey = `promoAdShown_${currentUser.uid}`;
        if (!sessionStorage.getItem(shownKey)) {
            // Give it a tiny delay to allow regular UI to render first
            setTimeout(() => {
                setShowPromoAdModal(true);
            }, 1500);
            sessionStorage.setItem(shownKey, 'true');
        }
    }
  }, [currentUser?.uid, appConfig?.loginPromoAd_enabled]);


  const [showCopyTrading, setShowCopyTrading] = useState(false);
  const [activeTrades, setActiveTrades] = useState<Trade[]>(() => {
    try {
      const lastUid = localStorage.getItem('bivaax_last_uid');
      const uid = auth.currentUser?.uid || lastUid;
      const cached = uid ? localStorage.getItem(`bivaax_active_trades_cache_${uid}`) : null;
      if (cached) {
        const parsed = JSON.parse(cached) as Trade[];
        return mergeAndDeduplicateActiveTrades([], parsed);
      }
      return [];
    } catch (e) {
      return [];
    }
  });
