  const validatePromoCode = async (codeToValidate?: string) => {
    const code = codeToValidate || promoCode;
    if (!code) {
      setPromoError("Enter a promo code");
      return;
    }
    setIsValidatingPromo(true);
    setIsVerifyingPromo(true);
    setPromoError("");
    try {
      const q = query(
        collection(db, 'promos'),
        where('code', '==', code.toUpperCase()),
        where('isActive', '==', true)
      );
      const snap = await getDocs(q);
      if (snap.empty) {
        setPromoError("Invalid or inactive promo code");
        setIsPromoValid(false);
        setPromoBonus(0);
        setAppliedPromo("");
      } else {
        const data = snap.docs[0].data();
        const now = Date.now();
        const expiry = data.expiryDate?.toDate ? data.expiryDate.toDate().getTime() : (typeof data.expiryDate === 'number' ? data.expiryDate : new Date(data.expiryDate).getTime());
        
        if (expiry < now) {
          setPromoError("Promo code has expired");
          setIsPromoValid(false);
          setPromoBonus(0);
          setAppliedPromo("");
        } else {
          setPromoBonus(data.bonusPercentage);
          setIsPromoValid(true);
          setPromoData(data);
          setAppliedPromo(code.toUpperCase());
          if (codeToValidate) setPromoCode(code.toUpperCase());
          toast.success(`Promo code applied: ${data.bonusPercentage}% bonus!`);
        }
      }
    } catch (e) {
      console.error("Promo validation error:", e);
      setPromoError("Validation failed. Try again.");
      setIsPromoValid(false);
    } finally {
      setIsValidatingPromo(false);
      setIsVerifyingPromo(false);
    }
  };
